import{_ as t,o as a,a as i,a2 as s}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"AI in Bagisto","description":"","frontmatter":{},"headers":[],"relativePath":"ai/introduction.md","filePath":"ai/introduction.md","lastUpdated":1789464754000}'),o={name:"ai/introduction.md"};function n(r,e,d,c,h,l){return a(),i("div",null,e[0]||(e[0]=[s('<h1 id="ai-in-bagisto" tabindex="-1">AI in Bagisto <a class="header-anchor" href="#ai-in-bagisto" aria-label="Permalink to &quot;AI in Bagisto&quot;">​</a></h1><p>Bagisto has AI in two places in the platform: Generative AI (Magic AI) in core produces content, and WebMCP in the Shop package declares storefront actions as tools for an AI agent in the shopper&#39;s browser. For the developers who extend Bagisto, agent skills give coding agents its conventions, and llms.txt gives AI tools this documentation as plain text.</p><h2 id="generative-agentic-and-the-difference" tabindex="-1">Generative, Agentic, and the Difference <a class="header-anchor" href="#generative-agentic-and-the-difference" aria-label="Permalink to &quot;Generative, Agentic, and the Difference&quot;">​</a></h2><p>The terms are used deliberately, because they describe different things:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning here</th><th>Where Bagisto has it</th></tr></thead><tbody><tr><td><strong>Generative AI</strong></td><td>A model produces content: text, translations, keywords, images</td><td><a href="./magic-ai.html">Generative AI (Magic AI)</a>, in core: text in the admin editor, product images in the admin, image-search keywords, review translation, the checkout success message</td></tr><tr><td><strong>Agentic AI</strong></td><td>An AI agent performs actions through tools, not only text</td><td><a href="./webmcp.html">WebMCP</a>: storefront tools a browser agent calls; <a href="./agent-skills.html">Agent Skills</a>: the conventions a coding agent follows while it changes your code</td></tr><tr><td><strong>Agentic commerce</strong></td><td>Commerce where AI helps produce a store&#39;s content and agents act on the storefront for a shopper</td><td>The direction the two add up to. Bagisto has no agent of its own that runs a store or shops by itself</td></tr></tbody></table><h2 id="what-stays-with-people" tabindex="-1">What Stays with People <a class="header-anchor" href="#what-stays-with-people" aria-label="Permalink to &quot;What Stays with People&quot;">​</a></h2><ul><li><strong>In the admin</strong>, Generative AI (Magic AI) returns text to a dialog in the editor and images to a dialog in the image uploader. Nothing reaches the product or page until the admin applies the result and saves the form.</li><li><strong>On the storefront</strong>, a review translation, a checkout success message or the keywords for an image search are shown to the shopper as they come back from the provider, and none of them is saved.</li><li><strong>A WebMCP tool</strong> fills a storefront form and submits it in the shopper&#39;s session, and the result is an ordinary page. No tool places an order or pays: <code>proceed_to_checkout</code> opens the checkout page, and <code>add_to_wishlist</code> sends a guest to the sign-in page.</li></ul><h2 id="pages-in-this-section" tabindex="-1">Pages in This Section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in This Section&quot;">​</a></h2><div class="ai-cards__group-title">For Your Store</div><div class="ai-cards"><a class="ai-card" href="/ai/magic-ai.html"><div class="ai-card__title">Generative AI (Magic AI)</div><div class="ai-card__desc"> Text and image generation in the admin, plus image search, review translation and a personalized checkout message on the storefront, on one of eight AI providers. </div></a><a class="ai-card" href="/ai/webmcp.html"><div class="ai-card__title">WebMCP</div><div class="ai-card__desc"> Storefront actions declared as tools for browser agents: open a product, add it to the wishlist, open the cart or the checkout, always in the shopper&#39;s own session. </div></a></div><div class="ai-cards__group-title">For Developers &amp; AI Agents</div><div class="ai-cards"><a class="ai-card" href="/ai/agent-skills.html"><div class="ai-card__title">Agent Skills</div><div class="ai-card__desc"> Skills that teach coding agents how Bagisto packages, themes, payment and shipping methods, tests and the API package are built. </div></a><a class="ai-card" href="/ai/llms-txt.html"><div class="ai-card__title">llms.txt</div><div class="ai-card__desc"> This documentation as two plain-text files, an index and the full text, for AI tools and assistants. </div></a></div><p>For the REST and GraphQL reference, <a href="https://api-docs.bagisto.com/api/build-with-ai/" target="_blank" rel="noreferrer">Build with AI</a> describes its own <code>llms.txt</code> and an optional MCP server that searches it.</p>',13)]))}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
